// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        bool success;
        // Call transfer and capture return value
        (success, ) = address(c).call(
            abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v)
        );
        // If the call succeeded, the return value must be true
        if (success) {
            // We need to check the actual return value of transfer
            // Use a low-level call to get the return data
            (bool ok, bytes memory ret) = address(c).call(
                abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v)
            );
            if (ok) {
                bool retVal = abi.decode(ret, (bool));
                assertTrue(retVal);
            }
        }
    }
}

